// ════════════════════════════════════════════════════════════════════════
// Flow #5 › Code – Validate Delivery Payload | نظام رادار SaaSAI v4.0 — مُصحح نهائي
// يتحقق من صحة بيانات طلب الإرسال (يدعم جميع تسميات الحقول والقنوات)
// ════════════════════════════════════════════════════════════════════════

// ── قراءة البيانات من أي مصدر (Webhook body أو مباشر) ─────────────────
const raw = $input.first()?.json || {};
const d = (raw.body && typeof raw.body === 'object' && !Array.isArray(raw.body)) 
  ? { ...raw.body, ...raw }  // ✅ دمج body مع الجذر للأمان
  : { ...raw };

// ── قائمة الحقول الإلزامية (مع دعم أسماء بديلة) ──────────────────────
const REQUIRED_FIELDS = [
  'lead_id',
  'lead_phone',
  'channel',
  // دعم كل من: message / custom_message / text
  d.message || d.custom_message || d.text ? null : 'message',
  'action_type',
  'priority',
  'template_id'
].filter(f => f !== null);

// ── القنوات المدعومة (بكل أشكال الكتابة) ────────────────────────────
const VALID_CHANNELS = [
  'whatsapp', 'telegram', 'email', 'sms', 
  'facebook', 'Facebook', 'FACEBOOK',
  'instagram', 'Instagram', 'INSTAGRAM'
];

// ── أنواع الإجراءات المدعومة ─────────────────────────────────────────
const VALID_ACTIONS = ['transactional', 'marketing', 'notification', 'alert'];

// ── أولويات الإرسال ──────────────────────────────────────────────────
const VALID_PRIORITIES = ['urgent', 'high', 'normal', 'low'];

// ── بدء التحقق ───────────────────────────────────────────────────────
const errors = [];

// 1. التحقق من الحقول الإلزامية (مع دعم الأسماء البديلة)
for (const field of REQUIRED_FIELDS) {
  // للحقل المرن (رسالة)
  if (field === 'message') {
    const value = d.message || d.custom_message || d.text;
    if (!value || (typeof value === 'string' && value.trim() === '')) {
      errors.push(`Missing required field: message (or custom_message/text)`);
    }
  } 
  // للحقول الأخرى
  else {
    const value = d[field];
    if (value === undefined || value === null || (typeof value === 'string' && value.trim() === '')) {
      errors.push(`Missing required field: ${field}`);
    }
  }
}

// 2. التحقق من صحة القناة (مع تطبيع الحالة)
const channelRaw = d.channel || '';
const channelNormalized = channelRaw.toLowerCase();
if (channelRaw && !VALID_CHANNELS.includes(channelRaw) && !VALID_CHANNELS.includes(channelNormalized)) {
  errors.push(`Invalid channel: ${channelRaw}. Must be one of: whatsapp, telegram, email, sms, facebook, instagram`);
}

// 3. التحقق من نوع الإجراء
if (d.action_type && !VALID_ACTIONS.includes(d.action_type.toLowerCase())) {
  errors.push(`Invalid action_type: ${d.action_type}. Must be one of: ${VALID_ACTIONS.join(', ')}`);
}

// 4. التحقق من الأولوية
if (d.priority && !VALID_PRIORITIES.includes(d.priority.toLowerCase())) {
  errors.push(`Invalid priority: ${d.priority}. Must be one of: ${VALID_PRIORITIES.join(', ')}`);
}

// 5. التحقق من طول الرسالة (للقنوات النصية)
const messageText = d.message || d.custom_message || d.text || '';
if (['whatsapp', 'telegram', 'sms', 'facebook', 'instagram'].includes(channelNormalized) && messageText) {
  if (messageText.length > 4000) {
    errors.push(`Message too long for ${channelRaw}: ${messageText.length} chars (max: 4000)`);
  }
}

// 6. التحقق من تنسيق الهاتف للقنوات التي تتطلبه
if (['whatsapp', 'sms'].includes(channelNormalized) && d.lead_phone) {
  const phoneRegex = /^\+\d{8,15}$/;
  const cleanPhone = d.lead_phone.replace(/[\s\-\.\(\)]/g, '');
  if (!phoneRegex.test(cleanPhone)) {
    errors.push(`Invalid phone format for ${channelRaw}: ${d.lead_phone}`);
  }
}

// 7. التحقق من personalization إذا وُجدت
if (d.personalization && typeof d.personalization === 'object') {
  if (d.personalization.name && d.personalization.name.length > 100) {
    errors.push(`personalization.name too long: ${d.personalization.name.length} chars`);
  }
}

// ── تحديد نتيجة التحقق ───────────────────────────────────────────────
const is_valid = errors.length === 0;

// ── استخراج الرسالة الموحدة ─────────────────────────────────────────
const unifiedMessage = d.message || d.custom_message || d.text || '';

// ── الإخراج النهائي ──────────────────────────────────────────────────
return [{
  json: {
    ...d,  // ✅ تمرير جميع الحقول الأصلية
    // ✅ حقل التحكم الرئيسي للعقدة الشرطية
    is_valid: is_valid,

    // تفاصيل التحقق للتقارير
    validation_errors: is_valid ? [] : errors,
    error_count: errors.length,
    validated_at: new Date().toISOString(),

    // حقول موحدة للمعالجة اللاحقة
    channel_normalized: channelNormalized,
    priority_normalized: d.priority?.toLowerCase() || 'normal',
    action_normalized: d.action_type?.toLowerCase() || 'transactional',
    message: unifiedMessage,  // ✅ حقل موحد للرسالة

    // معاينة الرسالة للإرسال
    message_preview: unifiedMessage ? unifiedMessage.substring(0, 200) + (unifiedMessage.length > 200 ? '...' : '') : '',

    // طابع زمني للمعالجة
    processed_at: new Date().toISOString()
  }
}];

// ─── Consent + Transactional Check ──────────────────────────────────────────
// Re-attach original payload (consent query may return empty array)
const originalPayload = $('Code – Validate Delivery Payload').first().json;
const consentItems = $input.all();

// Has consent if: at least one consent record found OR action is transactional/sales
const hasConsent = consentItems.some(i => i.json?.consent_given === true || i.json?.phone);
const isTransactional = ['transactional', 'sales'].includes(originalPayload.action_type);
const consentOk = hasConsent || isTransactional;

return [{ json: {
  ...originalPayload,
  consent_ok: consentOk,
  consent_source: isTransactional ? 'transactional_bypass' : (hasConsent ? 'db_consent' : 'no_consent')
} }];

// ─── Rate Limiter per Recipient ──────────────────────────────────────────────
// Window: 1 hour (3600s), max: 5 messages per recipient per hour
// For urgent/transactional: skip rate limit
const d = $json;
const identifier = d.lead_phone || d.lead_email || 'unknown';
const windowMs = 3600 * 1000;
const maxPerWindow = d.priority === 'urgent' || d.action_type === 'transactional' ? 999 : 5;

const now = Date.now();
const key = 'dlv_rl:' + identifier;
const staticStore = $getWorkflowStaticData('node');
let history = staticStore[key] || [];
history = history.filter(ts => now - ts < windowMs);

const rate_limited = history.length >= maxPerWindow;

if (!rate_limited) {
  history.push(now);
  staticStore[key] = history;
}

return [{ json: {
  ...d,
  rate_limited,
  rate_count: history.length,
  rate_limit_reason: rate_limited ? `${history.length}/${maxPerWindow} messages in 1h` : ''
} }];

// ─── Multi-Channel Router: WhatsApp First + Email + Telegram ───────────────
const d = $input.first().json;

// ═══════════════════════════════════════════════════════════════════════════
// 1️⃣ تنسيق رقم الجوال + اكتشاف المفتاح الدولي تلقائيًا
// ═══════════════════════════════════════════════════════════════════════════

// 🗺️ خريطة الدول العربية (كود الدولة ← الاسم + علم)
const COUNTRY_MAP = {
  '966': 'السعودية 🇸🇦',
  '967': 'اليمن 🇾🇪',
  '971': 'الإمارات 🇦🇪',
  '965': 'الكويت 🇰🇼',
  '973': 'البحرين 🇧🇭',
  '974': 'قطر 🇶🇦',
  '968': 'عمان 🇴🇲',
  '20': 'مصر 🇪🇬',
  '962': 'الأردن 🇯🇴',
  '963': 'سوريا 🇸🇾',
  '961': 'لبنان 🇱🇧',
  '212': 'المغرب 🇲🇦',
  '213': 'الجزائر 🇩🇿',
  '216': 'تونس 🇹🇳',
  '249': 'السودان 🇸🇩',
  '964': 'العراق 🇮🇶',
  '970': 'فلسطين 🇵🇸',
  '90': 'تركيا 🇹🇷'
};

// 📱 دالة تنسيق الرقم واكتشاف الدولة
const normalizePhone = (raw) => {
  if (!raw) return null;

  // تنظيف: إزالة كل ما عدا الأرقام و +
  let cleaned = raw.replace(/[^\d+]/g, '');

  // تحويل 00 إلى +
  if (cleaned.startsWith('00')) cleaned = '+' + cleaned.slice(2);

  // إذا لم يبدأ بـ +، نحاول استنتاج الدولة من نمط الرقم
  if (!cleaned.startsWith('+')) {
    // 🇸🇦 السعودية: يبدأ بـ 5 ويتكون من 9 أرقام (مثل: 05xxxxxxxx)
    if (/^5\d{8}$/.test(cleaned)) {
      cleaned = '+966' + cleaned;
    }
    // 🇾🇪 اليمن: يبدأ بـ 7 ويتكون من 9 أرقام (مثل: 07xxxxxxxx)
    else if (/^7\d{8}$/.test(cleaned)) {
      cleaned = '+967' + cleaned;
    }
    // 🇦🇪 الإمارات: يبدأ بـ 50/52/54/55/56 ويتكون من 9 أرقام
    else if (/^(50|52|54|55|56)\d{7}$/.test(cleaned)) {
      cleaned = '+971' + cleaned;
    }
    // 🇰🇼 الكويت: 8 أرقام يبدأ بـ 5/6/9
    else if (cleaned.length === 8 && /^[569]\d{7}$/.test(cleaned)) {
      cleaned = '+965' + cleaned;
    }
    // 🇧🇭 البحرين: 8 أرقام
    else if (cleaned.length === 8 && /^[369]\d{7}$/.test(cleaned)) {
      cleaned = '+973' + cleaned;
    }
    // 🇶🇦 قطر: 8 أرقام يبدأ بـ 3/5/6/7
    else if (cleaned.length === 8 && /^[3567]\d{7}$/.test(cleaned)) {
      cleaned = '+974' + cleaned;
    }
    // 🇴🇲 عمان: 8 أرقام يبدأ بـ 9
    else if (cleaned.length === 8 && /^9\d{7}$/.test(cleaned)) {
      cleaned = '+968' + cleaned;
    }
    // 🇪🇬 مصر: 11 رقم يبدأ بـ 01 (مثل: 010/011/012/015)
    else if (/^01[0125]\d{8}$/.test(cleaned)) {
      cleaned = '+20' + cleaned.slice(1); // نحذف الصفر الأول
    }
    // حل عام: إذا كان الرقم ≥ 8 أرقام، نضيف +
    else if (cleaned.length >= 8) {
      cleaned = '+' + cleaned;
    }
  }

  // التحقق النهائي: +[كود دولة 1-3 أرقام][8-15 رقم إجمالي]
  const isValid = cleaned.match(/^\+\d{8,15}$/);
  return isValid ? cleaned : null;
};

// تطبيق التنسيق على رقم العميل
const phoneRaw = d.lead_phone || d.phone || '';
const phoneNormalized = normalizePhone(phoneRaw);

// ✅ استخراج كود الدولة بشكل صحيح (1-3 أرقام فقط بعد +)
const countryCode = phoneNormalized?.match(/^\+(\d{1,3})/)?.[1] || null;

// ✅ تحديد اسم الدولة من الخريطة (الإصلاح: استخدام phoneCountry في المخرجات)
const phoneCountry = countryCode ? (COUNTRY_MAP[countryCode] || `أخرى 🌍 (كود: +${countryCode})`) : null;

// ✅ التحقق من صحة الرقم
const phoneIsValid = !!phoneNormalized;

// ═══════════════════════════════════════════════════════════════════════════
// 2️⃣ تحديد القنوات المتاحة (متعددة) مع أولوية واتساب
// ═══════════════════════════════════════════════════════════════════════════
const channels = {
  whatsapp: {
    available: phoneIsValid,
    priority: 1, // 🥇 الأولوية القصوى
    reason: phoneIsValid ? 'phone_number_available' : 'no_valid_phone'
  },
  email: {
    available: !!(d.lead_email || d.email),
    priority: 2, // 🥈 ثانيًا
    reason: (d.lead_email || d.email) ? 'email_available' : 'no_email'
  },
  telegram: {
    available: !!(d.telegram_id || d.telegram_username || d.platform === 'telegram'),
    priority: 3, // 🥉 ثالثًا
    reason: (d.telegram_id || d.telegram_username) ? 'telegram_available' : 'no_telegram'
  }
};

// قائمة القنوات المفعلة (للتكرار عليها في الإرسال)
const enabledChannels = Object.entries(channels)
  .filter(([_, cfg]) => cfg.available)
  .sort((a, b) => a[1].priority - b[1].priority)
  .map(([name]) => name);

// ═══════════════════════════════════════════════════════════════════════════
// 3️⃣ استخراج نية العميل من الرسالة لتخصيص الرد
// ═══════════════════════════════════════════════════════════════════════════
const extractIntent = (msg) => {
  if (!msg) return 'general_inquiry';
  const m = msg.toLowerCase();
  if (m.includes('حجز') || m.includes('أحجز') || m.includes('booking') || m.includes('reserve')) return 'booking_request';
  if (m.includes('سعر') || m.includes('كم') || m.includes('cost') || m.includes('price')) return 'price_inquiry';
  if (m.includes('إلغاء') || m.includes('تعديل') || m.includes('cancel') || m.includes('change')) return 'modification_request';
  if (m.includes('شكوى') || m.includes('مشكلة') || m.includes('complaint')) return 'complaint';
  if (m.includes('عاجل') || m.includes('فوري') || m.includes('urgent') || m.includes('now')) return 'urgent_request';
  return 'general_inquiry';
};

const intent = extractIntent(d.message || d.custom_message || '');
const intentLabel = {
  'booking_request': '📋 طلب حجز جديد',
  'price_inquiry': '💰 استفسار عن الأسعار',
  'modification_request': '🔄 طلب تعديل/إلغاء',
  'complaint': '⚠️ شكوى أو ملاحظة',
  'urgent_request': '🔴 طلب عاجل',
  'general_inquiry': '💬 استفسار عام'
}[intent];

// ═══════════════════════════════════════════════════════════════════════════
// 4️⃣ بناء الرسائل الاحترافية لكل قناة
// ═══════════════════════════════════════════════════════════════════════════
const p = d.personalization || {};
const prefs = d.preferences || {};
const meta = d.metadata || {};
const customerName = p.name || d.lead_name || d.name || 'عزيزي';
const rawMessage = (d.message || d.custom_message || d.text || '').substring(0, 400);
const slaMinutes = meta.sla_minutes || (d.priority === 'urgent' ? 15 : 30);

// 📱 رسالة واتساب (نص واضح، مختصر، مع إيموجي)
const buildWhatsAppMessage = () => {
  return `*أهلاً وسهلاً بك يا ${customerName}* 👋🌹

${intentLabel}
_"${rawMessage}"_

✅ *تم استلام طلبك* وسيتواصل معك فريق المبيعات خلال *${slaMinutes} دقيقة* على الأكثر.

🏨 *تفضيلات إقامتك:*
• التصنيف: ${prefs.stars === '5star' ? '⭐⭐⭐⭐⭐ 5 نجوم' : prefs.stars === '4star' ? '⭐⭐⭐⭐ 4 نجوم' : 'غير محدد'}
• الميزانية: ${prefs.budget === 'luxury' ? '💎 فاخر' : prefs.budget === 'mid' ? '💰 متوسط' : 'غير محدد'}
• عدد الأشخاص: ${p.pax || prefs.group || 'غير محدد'}

🆔 معرف الطلب: \`${d.lead_id}\`
📞 للتواصل: ${phoneNormalized || d.lead_phone} ${phoneCountry?.split(' ')[1] || ''}

_فريق SaaSAI المكرمة — خدمتك أولويتنا_ 🕌`;
};

// 📧 رسالة الإيميل (HTML احترافي)
const buildEmailMessage = () => {
  const subjectMap = {
    'booking_request': '✅ تأكيد استلام طلب حجزك في مكة',
    'price_inquiry': '💰 رد على استفسارك عن أسعار خدمات SaaSAI',
    'modification_request': '🔄 تحديث حالة طلب التعديل',
    'complaint': '⚠️ شكرًا لملاحظاتك — جاري المتابعة الفورية',
    'urgent_request': '🔴 طلبك العاجل تحت المعالجة الآن',
    'general_inquiry': '💬 شكرًا لتواصلك مع خدمات SaaSAI'
  };

  return {
    subject: subjectMap[intent] || 'شكرًا لتواصلك معنا',
    html: `
<!DOCTYPE html>
<html dir="rtl" lang="ar">
<head>
  <meta charset="UTF-8">
  <style>
    body { font-family: 'Segoe UI', Tahoma, sans-serif; line-height: 1.6; color: #333; max-width: 600px; margin: auto; }
    .header { background: linear-gradient(135deg, #1a73e8, #0d47a1); color: white; padding: 20px; text-align: center; border-radius: 8px 8px 0 0; }
    .content { padding: 24px; background: #fff; border: 1px solid #e0e0e0; border-radius: 0 0 8px 8px; }
    .badge { display: inline-block; padding: 4px 12px; border-radius: 20px; font-size: 12px; font-weight: bold; }
    .badge-urgent { background: #ffebee; color: #c62828; }
    .badge-booking { background: #e8f5e9; color: #2e7d32; }
    .badge-inquiry { background: #e3f2fd; color: #1565c0; }
    blockquote { border-right: 4px solid #1a73e8; padding-right: 16px; margin: 16px 0; color: #555; background: #f5f5f5; padding: 12px 16px; border-radius: 4px; }
    .preferences { background: #f9f9f9; padding: 16px; border-radius: 8px; margin: 16px 0; }
    .preferences li { margin: 8px 0; }
    .footer { text-align: center; padding: 16px; color: #666; font-size: 13px; border-top: 1px solid #eee; margin-top: 24px; }
    code { background: #f1f1f1; padding: 2px 6px; border-radius: 4px; font-family: monospace; }
  </style>
</head>
<body>
  <div class="header">
    <h2 style="margin:0;">🕌 SaaSAI للأتمتة</h2>
    <p style="margin:4px 0 0; opacity:0.9;">خدمتك أولويتنا</p>
  </div>
  <div class="content">
    <p>أهلاً وسهلاً بك يا <strong>${customerName}</strong> 👋🌹</p>

    <p>
      <span class="badge ${intent === 'urgent_request' ? 'badge-urgent' : intent === 'booking_request' ? 'badge-booking' : 'badge-inquiry'}">
        ${intentLabel}
      </span>
    </p>

    <blockquote>
      ${rawMessage.replace(/\n/g, '<br>')}
    </blockquote>

    <p>✅ <strong>تم استلام طلبك بنجاح</strong>، وسيتواصل معك فريق المبيعات المختص خلال <strong>${slaMinutes} دقيقة</strong> على الأكثر.</p>

    <div class="preferences">
      <h4 style="margin:0 0 12px; color:#1a73e8;">🏨 تفضيلات إقامتك:</h4>
      <ul style="margin:0; padding-right:20px;">
        <li>⭐ <strong>التصنيف:</strong> ${prefs.stars === '5star' ? '5 نجوم فاخر' : prefs.stars === '4star' ? '4 نجوم مميز' : 'غير محدد'}</li>
        <li>💰 <strong>الميزانية:</strong> ${prefs.budget === 'luxury' ? 'فاخر' : prefs.budget === 'mid' ? 'متوسط' : 'غير محدد'}</li>
        <li>👥 <strong>عدد الأشخاص:</strong> ${p.pax || prefs.group || 'غير محدد'}</li>
      </ul>
    </div>

    <div class="footer">
      <p style="margin:0;">
        🆔 معرف الطلب: <code>${d.lead_id}</code><br>
        📞 للتواصل: ${phoneNormalized || d.lead_phone || 'غير متاح'}<br>
        🕐 وقت الاستلام: ${new Date(meta.sent_at || Date.now()).toLocaleTimeString('ar-SA')}
      </p>
      <p style="margin:8px 0 0; font-style:italic;">
        🕌 فريق SaaSAI المكرمة — نتمنى لك إقامة طيبة في رحاب البيت الحرام
      </p>
    </div>
  </div>
</body>
</html>`
  };
};

// ✈️ رسالة تليجرام (ماركداون كامل + إيموجي + تنسيق غني)
const buildTelegramMessage = () => {
  return `*🕌 SaaSAI للأتمتة — تأكيد استلام الطلب*

*أهلاً وسهلاً بك يا ${customerName}* 👋🌹

${intentLabel}
_${rawMessage.replace(/\n/g, '\n')}_

✅ *تم استلام طلبك بنجاح*
⏱️ سيتواصل معك فريق المبيعات خلال *${slaMinutes} دقيقة* كحد أقصى

*🏨 تفضيلات إقامتك:*
• ⭐ التصنيف: ${prefs.stars === '5star' ? '⭐⭐⭐⭐⭐ 5 نجوم' : prefs.stars === '4star' ? '⭐⭐⭐⭐ 4 نجوم' : 'غير محدد'}
• 💰 الميزانية: ${prefs.budget === 'luxury' ? '💎 فاخر' : prefs.budget === 'mid' ? '💰 متوسط' : 'غير محدد'}
• 👥 العدد: ${p.pax || prefs.group || 'غير محدد'} شخص

🆔 *معرف الطلب:* \`${d.lead_id}\`
📞 *للتواصل:* ${phoneNormalized || d.lead_phone} ${phoneCountry?.split(' ')[1] || ''}

_فريقنا جاهز لخدمتك على مدار الساعة_ 🤲`;
};

// ═══════════════════════════════════════════════════════════════════════════
// 5️⃣ تجميع المخرجات النهائية (دعم متعدد القنوات)
// ═══════════════════════════════════════════════════════════════════════════

// تحضير الرسائل لكل قناة مفعلة
const messagesByChannel = {};
if (channels.whatsapp.available) {
  messagesByChannel.whatsapp = buildWhatsAppMessage();
}
if (channels.email.available) {
  const email = buildEmailMessage();
  messagesByChannel.email = {
    text: email.html.replace(/<[^>]*>/g, '').substring(0, 500),
    subject: email.subject,
    html: email.html
  };
}
if (channels.telegram.available) {
  messagesByChannel.telegram = buildTelegramMessage();
}

// حساب إحصائيات الرسالة
const primaryMessage = messagesByChannel[enabledChannels[0]] || '';
const charCount = Buffer.byteLength(typeof primaryMessage === 'string' ? primaryMessage : JSON.stringify(primaryMessage), 'utf8');

return [{
  json: {
    // === الهوية والبيانات الأساسية ===
    ...d,

    // === تنسيق الجوال والدولة ✅ (الإصلاح هنا) ===
    phone_normalized: phoneNormalized,
    phone_country_code: countryCode,
    phone_country: phoneCountry,  // ✅ يستخدم COUNTRY_MAP الكاملة (17+ دولة)
    phone_is_valid: phoneIsValid,

    // === القنوات المتاحة والمفعلة ===
    channels_available: Object.fromEntries(
      Object.entries(channels).map(([k, v]) => [k, v.available])
    ),
    channels_enabled: enabledChannels,
    primary_channel: enabledChannels[0] || 'none',

    // === نية العميل ===
    detected_intent: intent,
    intent_label: intentLabel,

    // === الرسائل الجاهزة لكل قناة ===
    messages: messagesByChannel,

    // === رسالة افتراضية للعقد التي تدعم قناة واحدة ===
    final_message: messagesByChannel.whatsapp || messagesByChannel.email?.text || messagesByChannel.telegram || '',

    // === بيانات الإيميل (إذا وُجد) ===
    email_subject: messagesByChannel.email?.subject || null,
    email_html: messagesByChannel.email?.html || null,

    // === بيانات فنية ===
    char_count: charCount,
    is_long_message: charCount > 1000,
    message_language: 'ar',

    // === جاهزية الإرسال ===
    ready_to_send: enabledChannels.length > 0,
    send_to_multiple: enabledChannels.length > 1,
    send_error: enabledChannels.length === 0 ? 'no_valid_channel_found' : null,

    // === للتدقيق والتحليل ===
    routing_applied_at: new Date().toISOString(),
    sla_minutes: slaMinutes,
    priority_score: d.priority === 'urgent' || intent === 'urgent_request' ? 100 : meta.score || 0
  }
}];

// ⏸️ Twilio SMS PAUSED – re-enable when Twilio account ready
const d=$input.first().json;
return[{json:{...d,_sms_paused:true,message_status:'queued_paused',sid:null}}];

// ─── Evaluate Delivery Result — Fixed for TimelinesAI + Telegram + Email ─────
const d = $input.first().json;
const originalPayload = $('Code – Personalize Message').first().json;

// استخراج القناة من البيانات الأصلية (الأكثر موثوقية)
const channel = originalPayload.primary_channel || originalPayload.channel || d.channel || 'unknown';

let success = false;
let message_id = '';
let error_detail = '';

// ═══════════════════════════════════════════════════════════════════════════
// ✅ معالجة الاستجابة حسب القناة ونوع الـ API
// ═══════════════════════════════════════════════════════════════════════════

if (channel === 'whatsapp') {
  // ── TimelinesAI Format ───────────────────────────────────────────────────
  // { "status": "ok", "data": { "message_uid": "..." } }
  if (d.status === 'ok' && d.data?.message_uid) {
    success = true;
    message_id = d.data.message_uid;
  }
  // ── Meta Graph API Format (للمقارنة) ─────────────────────────────────────
  else if (d.messages?.[0]?.id) {
    success = true;
    message_id = d.messages[0].id;
  }
  // ── fallback: تحقق من رمز الحالة ─────────────────────────────────────────
  else if (d.statusCode && d.statusCode < 400) {
    success = true;
    message_id = d.message_id || d.id || '';
  }
  // ── فشل ─────────────────────────────────────────────────────────────────
  else {
    error_detail = d.error?.message || d.data?.error || JSON.stringify(d).substring(0, 200);
  }

} else if (channel === 'telegram') {
  // ── Telegram Bot API Format ──────────────────────────────────────────────
  // { "ok": true, "result": { "message_id": 12345 } }
  if (d.ok === true && d.result?.message_id) {
    success = true;
    message_id = String(d.result.message_id);
  }
  // ── n8n Telegram Node wraps response ─────────────────────────────────────
  else if (d.message_id) {
    success = true;
    message_id = String(d.message_id);
  }
  // ── فشل ─────────────────────────────────────────────────────────────────
  else {
    error_detail = d.description || d.error?.message || JSON.stringify(d).substring(0, 200);
  }

} else if (channel === 'email') {
  // ── Gmail / SMTP Format ─────────────────────────────────────────────────
  // { "messageId": "<xxx@mail.gmail.com>" } أو { "id": "..." }
  if (d.messageId || d.id || d.statusCode === 200 || d.statusCode === 202) {
    success = true;
    message_id = d.messageId || d.id || 'sent';
  }
  // ── فشل ─────────────────────────────────────────────────────────────────
  else {
    error_detail = d.error?.message || d.response?.data?.error || JSON.stringify(d).substring(0, 200);
  }

} else {
  // قناة غير معروفة
  error_detail = `unhandled channel: ${channel}`;
}

// ═══════════════════════════════════════════════════════════════════════════
// 📦 المخرج النهائي الموحد
// ═══════════════════════════════════════════════════════════════════════════

return [{
  json: {
    // === الحفاظ على كل البيانات الأصلية ===
    ...originalPayload,

    // === حالة التسليم ===
    delivery_status: success ? 'delivered' : 'failed',
    delivery_channel: channel,
    message_id: message_id || null,
    error_detail: error_detail || null,
    delivered_at: success ? new Date().toISOString() : null,

    // === الاستجابة الخام للتدقيق ===
    raw_response: d,

    // === مفيد للتحليل لاحقًا ===
    is_first_attempt: true,
    retry_count: 0,
    next_retry_at: !success ? new Date(Date.now() + 300000).toISOString() : null // أعد المحاولة بعد 5 دقائق
  }
}];

